#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <new>

struct Node {
    Node* left;
    Node* right;
};

class NodeArena {
public:
    explicit NodeArena(std::size_t capacity)
        : data_(static_cast<Node*>(::operator new(capacity * sizeof(Node)))),
          position_(0) {}

    ~NodeArena() {
        ::operator delete(data_);
    }

    NodeArena(const NodeArena&) = delete;
    NodeArena& operator=(const NodeArena&) = delete;

    Node* makeTree(int depth) {
        Node* node = &data_[position_++];
        if (depth == 0) {
            node->left = nullptr;
            node->right = nullptr;
        } else {
            node->left = makeTree(depth - 1);
            node->right = makeTree(depth - 1);
        }
        return node;
    }

    std::size_t mark() const {
        return position_;
    }

    void rewind(std::size_t position) {
        position_ = position;
    }

private:
    Node* data_;
    std::size_t position_;
};

static std::uint64_t nodeCount(const Node* node) {
    if (node->left == nullptr) {
        return 1;
    }
    return 1 + nodeCount(node->left) + nodeCount(node->right);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    const int n = std::atoi(argv[1]);
    const int stretchDepth = n + 1;

    if (n + 2 >= static_cast<int>(std::numeric_limits<std::size_t>::digits)) {
        return 1;
    }

    const std::size_t arenaCapacity =
        (std::size_t{1} << (n + 2)) - 1;

    NodeArena arena(arenaCapacity);

    Node* stretchTree = arena.makeTree(stretchDepth);
    std::cout << "stretch tree of depth " << stretchDepth
              << "\t check: " << nodeCount(stretchTree) << '\n';
    arena.rewind(0);

    Node* longLivedTree = arena.makeTree(n);
    const std::size_t longLivedMark = arena.mark();

    for (int depth = 4; depth <= n; depth += 2) {
        const int exponent = n - depth + 4;
        const std::uint64_t iterations = std::uint64_t{1} << exponent;
        std::uint64_t checksum = 0;

        for (std::uint64_t i = 0; i < iterations; ++i) {
            Node* tree = arena.makeTree(depth);
            checksum += nodeCount(tree);
            arena.rewind(longLivedMark);
        }

        std::cout << iterations << "\t trees of depth " << depth
                  << "\t check: " << checksum << '\n';
    }

    std::cout << "long lived tree of depth " << n
              << "\t check: " << nodeCount(longLivedTree) << '\n';

    return 0;
}
