#include <algorithm>
#include <atomic>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <thread>
#include <vector>

namespace {

constexpr int MAX_N = 20;
constexpr std::uint64_t CHUNK_SIZE = 32768;

struct alignas(64) Result {
    std::int64_t checksum = 0;
    int maxFlips = 0;
};

inline void rotateLeft(std::uint8_t* permutation, int length) {
    const std::uint8_t first = permutation[0];
    for (int i = 0; i + 1 < length; ++i) {
        permutation[i] = permutation[i + 1];
    }
    permutation[length - 1] = first;
}

void initializePermutation(std::uint64_t index,
                           int n,
                           const std::uint64_t* factorial,
                           std::uint8_t* permutation,
                           std::uint8_t* count) {
    for (int i = 0; i < n; ++i) {
        permutation[i] = static_cast<std::uint8_t>(i);
        count[i] = 0;
    }

    std::uint8_t temporary[MAX_N];

    for (int i = n - 1; i > 0; --i) {
        const int rotations = static_cast<int>(index / factorial[i]);
        index %= factorial[i];
        count[i] = static_cast<std::uint8_t>(rotations);

        if (rotations != 0) {
            std::memcpy(temporary, permutation,
                        static_cast<std::size_t>(rotations));
            std::memmove(permutation, permutation + rotations,
                         static_cast<std::size_t>(i + 1 - rotations));
            std::memcpy(permutation + i + 1 - rotations, temporary,
                        static_cast<std::size_t>(rotations));
        }
    }
}

inline void nextPermutation(std::uint8_t* permutation,
                            std::uint8_t* count,
                            int n) {
    for (int r = 1; r < n; ++r) {
        rotateLeft(permutation, r + 1);
        if (++count[r] <= r) {
            return;
        }
        count[r] = 0;
    }
}

inline int countFlips(const std::uint8_t* permutation, int n) {
    if (permutation[0] == 0) {
        return 0;
    }

    std::uint8_t copy[MAX_N];
    std::memcpy(copy, permutation, static_cast<std::size_t>(n));

    int flips = 0;
    while (copy[0] != 0) {
        int left = 0;
        int right = copy[0];
        while (left < right) {
            std::swap(copy[left++], copy[right--]);
        }
        ++flips;
    }
    return flips;
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    char* end = nullptr;
    const long parsed = std::strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || parsed < 1 || parsed > MAX_N) {
        return 1;
    }

    const int n = static_cast<int>(parsed);

    std::uint64_t factorial[MAX_N + 1];
    factorial[0] = 1;
    for (int i = 1; i <= n; ++i) {
        factorial[i] = factorial[i - 1] * static_cast<std::uint64_t>(i);
    }

    const std::uint64_t totalPermutations = factorial[n];
    const std::uint64_t totalChunks =
        (totalPermutations + CHUNK_SIZE - 1) / CHUNK_SIZE;

    unsigned threadCount = std::thread::hardware_concurrency();
    if (threadCount == 0) {
        threadCount = 1;
    }
    threadCount = std::min<unsigned>(threadCount, 64);
    threadCount = std::min<std::uint64_t>(threadCount, totalChunks);

    std::atomic<std::uint64_t> nextChunk{0};
    std::vector<Result> results(threadCount);
    std::vector<std::thread> threads;
    threads.reserve(threadCount);

    for (unsigned threadId = 0; threadId < threadCount; ++threadId) {
        threads.emplace_back([&, threadId] {
            std::int64_t checksum = 0;
            int maximumFlips = 0;

            std::uint8_t permutation[MAX_N];
            std::uint8_t count[MAX_N];

            while (true) {
                const std::uint64_t chunk =
                    nextChunk.fetch_add(1, std::memory_order_relaxed);
                if (chunk >= totalChunks) {
                    break;
                }

                const std::uint64_t begin = chunk * CHUNK_SIZE;
                const std::uint64_t endIndex =
                    std::min(begin + CHUNK_SIZE, totalPermutations);

                initializePermutation(begin, n, factorial, permutation, count);

                for (std::uint64_t index = begin; index < endIndex; ++index) {
                    const int flips = countFlips(permutation, n);
                    maximumFlips = std::max(maximumFlips, flips);

                    if ((index & 1U) == 0) {
                        checksum += flips;
                    } else {
                        checksum -= flips;
                    }

                    if (index + 1 < endIndex) {
                        nextPermutation(permutation, count, n);
                    }
                }
            }

            results[threadId].checksum = checksum;
            results[threadId].maxFlips = maximumFlips;
        });
    }

    for (std::thread& thread : threads) {
        thread.join();
    }

    std::int64_t checksum = 0;
    int maximumFlips = 0;
    for (const Result& result : results) {
        checksum += result.checksum;
        maximumFlips = std::max(maximumFlips, result.maxFlips);
    }

    std::cout << checksum << '\n'
              << "Pfannkuchen(" << n << ") = " << maximumFlips << '\n';

    return 0;
}
