                denominator = static_cast<std::uint64_t>(i) * (i + 1) / 2 + 1;
                increment = static_cast<std::uint64_t>(i) + 2;
            } else {
                denominator = static_cast<std::uint64_t>(i) * (i + 1) / 2 + i + 1;
                increment = static_cast<std::uint64_t>(i) + 1;
            }

            double sum0 = 0.0;
            double sum1 = 0.0;
            double sum2 = 0.0;
            double sum3 = 0.0;

