                const std::uint64_t d3 = d2 + increment + 2;

                sum0 += input[j]     / static_cast<double>(d0);
                sum1 += input[j + 1] / static_cast<double>(d1);
                sum2 += input[j + 2] / static_cast<double>(d2);
                sum3 += input[j + 3] / static_cast<double>(d3);

                denominator = d3 + increment + 3;
                increment += 4;
            }

            for (; j < n; ++j) {
                sum0 += input[j] / static_cast<double>(denominator);
                denominator += increment++;
            }

            output[i] = (sum0 + sum1) + (sum2 + sum3);
        }
    };

    if (thread_count == 1) {
        worker(0, n);
        return;
    }

    std::vector<std::thread> threads;
    threads.reserve(thread_count - 1);

    for (unsigned t = 0; t + 1 < thread_count; ++t) {
        const std::size_t begin = n * t / thread_count;
        const std::size_t end = n * (t + 1) / thread_count;
        threads.emplace_back(worker, begin, end);
