class OutputBuffer {
    static constexpr std::size_t Capacity = 1u << 20;
    std::unique_ptr<char[]> buffer_;
    std::size_t used_ = 0;

public:
    OutputBuffer() : buffer_(new char[Capacity]) {}

    ~OutputBuffer() {
        flush();
    }

    void flush() {
        if (used_ != 0) {
            std::fwrite(buffer_.get(), 1, used_, stdout);
            used_ = 0;
        }
    }

    char* reserve(std::size_t size) {
        if (used_ + size > Capacity) {
            flush();
        }
        return buffer_.get() + used_;
    }

    void commit(std::size_t size) {
        used_ += size;
    }

    void write(const char* data, std::size_t size) {
        if (size > Capacity) {
            flush();
            std::fwrite(data, 1, size, stdout);
            return;
        }
        char* destination = reserve(size);
        std::memcpy(destination, data, size);
        commit(size);
    }
};

