    int seed,
    const char* symbols,
    const double* cumulative,
    std::size_t count
) {
    const double r = static_cast<double>(seed) / 139968.0;
    for (std::size_t i = 0; i < count; ++i) {
        if (cumulative[i] > r) {
            return symbols[i];
        }
    }
    return symbols[count - 1];
}

static void emit_cyclic_sequence(
    OutputBuffer& output,
    const char* cycle,
    std::size_t cycle_length,
    std::size_t phase,
    std::uint64_t length
) {
    while (length != 0) {
        const std::size_t line_length =
            static_cast<std::size_t>(std::min<std::uint64_t>(60, length));

        char* destination = output.reserve(line_length + 1);
        std::size_t remaining = line_length;
        std::size_t written = 0;

        while (remaining != 0) {
            const std::size_t part =
                std::min(remaining, cycle_length - phase);
            std::memcpy(destination + written, cycle + phase, part);

            written += part;
            remaining -= part;
            phase += part;
            if (phase == cycle_length) {
                phase = 0;
            }
        }

        destination[line_length] = '\n';
        output.commit(line_length + 1);
        length -= line_length;
    }
}

int main(int argc, char** argv) {
