        "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";
    static constexpr std::size_t alu_length = sizeof(alu) - 1;

    static constexpr char iub_symbols[] = {
        'a', 'c', 'g', 't',
        'B', 'D', 'H', 'K', 'M', 'N',
        'R', 'S', 'V', 'W', 'Y'
    };
    static constexpr double iub_probabilities[] = {
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
        0.02, 0.02, 0.02, 0.02, 0.02
    };

    static constexpr char homo_symbols[] = {'a', 'c', 'g', 't'};
    static constexpr double homo_probabilities[] = {
        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    };

    std::array<double, 15> iub_cumulative{};
    std::array<double, 4> homo_cumulative{};

    double total = 0.0;
    for (std::size_t i = 0; i < iub_cumulative.size(); ++i) {
        total += iub_probabilities[i];
        iub_cumulative[i] = total;
    }

    total = 0.0;
    for (std::size_t i = 0; i < homo_cumulative.size(); ++i) {
        total += homo_probabilities[i];
        homo_cumulative[i] = total;
    }

    static constexpr std::size_t generator_period = 139968;
    std::array<char, generator_period> iub_cycle{};
    std::array<char, generator_period> homo_cycle{};

    int seed = 42;
    for (std::size_t i = 0; i < generator_period; ++i) {
        seed = (seed * 3877 + 29573) % 139968;

        iub_cycle[i] = select_symbol(
            seed,
