struct Fragment {
    const char* text;
    int length;
    std::uint64_t code;
    std::uint64_t count;
    std::uint64_t mask;
};

static int nucleotide_code(char c) {
    switch (c) {
        case 'A': case 'a': return 0;
        case 'C': case 'c': return 1;
        case 'G': case 'g': return 2;
        case 'T': case 't': return 3;
        default: return -1;
    }
}

static std::uint64_t encode_fragment(const char* text) {
    std::uint64_t code = 0;
    for (const char* p = text; *p != '\0'; ++p) {
        code = (code << 2) | static_cast<std::uint64_t>(nucleotide_code(*p));
    }
    return code;
}

static std::string decode_kmer(unsigned value, int length) {
    static constexpr char bases[] = {'A', 'C', 'G', 'T'};
    std::string result(static_cast<std::size_t>(length), 'A');
    for (int i = length - 1; i >= 0; --i) {
        result[static_cast<std::size_t>(i)] = bases[value & 3U];
        value >>= 2;
    }
    return result;
}

static void print_frequencies(const std::uint64_t* counts,
                              int number_of_kmers,
                              int k) {
    struct Entry {
        std::string kmer;
        std::uint64_t count;
    };

    std::vector<Entry> entries;
    std::uint64_t total = 0;

    for (int i = 0; i < number_of_kmers; ++i) {
        total += counts[i];
        if (counts[i] != 0) {
            entries.push_back({decode_kmer(static_cast<unsigned>(i), k), counts[i]});
        }
    }

    std::sort(entries.begin(), entries.end(),
              [](const Entry& a, const Entry& b) {
                  if (a.count != b.count) {
                      return a.count > b.count;
                  }
                  return a.kmer < b.kmer;
              });

    for (const Entry& entry : entries) {
        const double percentage =
            total == 0 ? 0.0 : 100.0 * static_cast<double>(entry.count) /
                                      static_cast<double>(total);
        std::cout << entry.kmer << ' ' << percentage << '\n';
    }
    std::cout << '\n';
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    char* parse_end = nullptr;
    const long n = std::strtol(argv[1], &parse_end, 10);
    (void)n;
    (void)parse_end;

    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cout.imbue(std::locale::classic());

    std::array<std::uint64_t, 4> one_counts{};
    std::array<std::uint64_t, 16> two_counts{};

    std::array<Fragment, 5> fragments{{
        {"GGT", 3, 0, 0, 0},
        {"GGTA", 4, 0, 0, 0},
        {"GGTATT", 6, 0, 0, 0},
        {"GGTATTTTAATT", 12, 0, 0, 0},
        {"GGTATTTTAATTTATAGT", 18, 0, 0, 0}
    }};

    for (Fragment& fragment : fragments) {
        fragment.code = encode_fragment(fragment.text);
        fragment.mask = (std::uint64_t{1} << (2 * fragment.length)) - 1;
    }

    constexpr std::uint64_t rolling_mask =
        (std::uint64_t{1} << (2 * 18)) - 1;

    bool in_three = false;
    std::uint64_t rolling = 0;
    int valid_run = 0;

    std::string line;
    while (std::getline(std::cin, line)) {
        if (!line.empty() && line[0] == '>') {
            if (in_three) {
                break;
            }

            in_three =
                line.size() >= 6 &&
                line.compare(1, 5, "THREE") == 0 &&
                (line.size() == 6 ||
                 line[6] == ' ' ||
                 line[6] == '\t' ||
                 line[6] == '\r');
            continue;
        }

        if (!in_three) {
            continue;
        }

        for (char c : line) {
            const int value = nucleotide_code(c);
            if (value < 0) {
                if (c != ' ' && c != '\t' && c != '\r' && c != '\n') {
                    rolling = 0;
                    valid_run = 0;
                }
                continue;
            }

            rolling = ((rolling << 2) |
                       static_cast<std::uint64_t>(value)) & rolling_mask;
            ++valid_run;

            ++one_counts[static_cast<std::size_t>(value)];

            if (valid_run >= 2) {
                ++two_counts[static_cast<std::size_t>(rolling & 15U)];
            }

            for (Fragment& fragment : fragments) {
                if (valid_run >= fragment.length &&
                    (rolling & fragment.mask) == fragment.code) {
                    ++fragment.count;
                }
            }
        }
    }

    std::cout << std::fixed << std::setprecision(3);
    print_frequencies(one_counts.data(), 4, 1);
    print_frequencies(two_counts.data(), 16, 2);

    for (const Fragment& fragment : fragments) {
        std::cout << fragment.count << '\t' << fragment.text << '\n';
    }

    return 0;
}
