constexpr double PI = 3.141592653589793;
constexpr double SOLAR_MASS = 4.0 * PI * PI;
constexpr double DAYS_PER_YEAR = 365.24;
constexpr double DT = 0.01;

struct Body {
    double x, y, z;
    double vx, vy, vz;
    double mass;
};

static inline void interact(Body& a, Body& b) {
    const double dx = a.x - b.x;
    const double dy = a.y - b.y;
    const double dz = a.z - b.z;

    const double distance = std::sqrt(dx * dx + dy * dy + dz * dz);
    const double magnitude = DT / (distance * distance * distance);

    const double b_scale = b.mass * magnitude;
    const double a_scale = a.mass * magnitude;

    a.vx -= dx * b_scale;
    a.vy -= dy * b_scale;
    a.vz -= dz * b_scale;

    b.vx += dx * a_scale;
    b.vy += dy * a_scale;
    b.vz += dz * a_scale;
}

static void offset_momentum(Body bodies[5]) {
    double px = 0.0;
    double py = 0.0;
    double pz = 0.0;

    for (int i = 0; i < 5; ++i) {
        px += bodies[i].vx * bodies[i].mass;
        py += bodies[i].vy * bodies[i].mass;
        pz += bodies[i].vz * bodies[i].mass;
    }

    bodies[0].vx = -px / SOLAR_MASS;
    bodies[0].vy = -py / SOLAR_MASS;
    bodies[0].vz = -pz / SOLAR_MASS;
}

static double energy(const Body bodies[5]) {
    double result = 0.0;

    for (int i = 0; i < 5; ++i) {
        const Body& a = bodies[i];

        result += 0.5 * a.mass *
                  (a.vx * a.vx + a.vy * a.vy + a.vz * a.vz);

        for (int j = i + 1; j < 5; ++j) {
            const Body& b = bodies[j];
            const double dx = a.x - b.x;
            const double dy = a.y - b.y;
            const double dz = a.z - b.z;
            const double distance = std::sqrt(dx * dx + dy * dy + dz * dz);

            result -= (a.mass * b.mass) / distance;
        }
    }

    return result;
}

static void advance(Body bodies[5], long long steps) {
