        bodies[3].x += DT * bodies[3].vx;
        bodies[3].y += DT * bodies[3].vy;
        bodies[3].z += DT * bodies[3].vz;

        bodies[4].x += DT * bodies[4].vx;
        bodies[4].y += DT * bodies[4].vy;
