static inline bool is_mandelbrot(double cr, double ci) {
    // Points in the main cardioid or period-2 bulb are guaranteed members.
    const double y2 = ci * ci;
    const double x = cr - 0.25;
    const double q = x * x + y2;
    if (q * (q + x) <= 0.25 * y2) {
        return true;
    }

    const double bulb_x = cr + 1.0;
    if (bulb_x * bulb_x + y2 <= 0.0625) {
        return true;
    }

    double zr = 0.0;
    double zi = 0.0;
    double zr2 = 0.0;
    double zi2 = 0.0;

    for (int iteration = 0; iteration < 50; ++iteration) {
        zi = 2.0 * zr * zi + ci;
        zr = zr2 - zi2 + cr;
        zr2 = zr * zr;
        zi2 = zi * zi;

        if (zr2 + zi2 > 4.0) {
            return false;
        }
    }

    return true;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    char* end = nullptr;
    const long parsed = std::strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || parsed <= 0) {
        return 1;
    }

    const int n = static_cast<int>(parsed);
    const std::size_t bytes_per_row =
        (static_cast<std::size_t>(n) + 7u) / 8u;
    const std::size_t image_size =
        bytes_per_row * static_cast<std::size_t>(n);

    std::vector<double> real_coordinates(static_cast<std::size_t>(n));
    for (int x = 0; x < n; ++x) {
        real_coordinates[static_cast<std::size_t>(x)] =
            2.0 * static_cast<double>(x) / static_cast<double>(n) - 1.5;
    }

    std::vector<std::uint8_t> image(image_size, 0);

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
    for (int y = 0; y < n; ++y) {
        const double ci =
            2.0 * static_cast<double>(y) / static_cast<double>(n) - 1.0;
        std::uint8_t* row =
            image.data() + static_cast<std::size_t>(y) * bytes_per_row;

        for (int x = 0; x < n; ++x) {
            if (is_mandelbrot(
                    real_coordinates[static_cast<std::size_t>(x)], ci)) {
                row[static_cast<std::size_t>(x) >> 3] |=
                    static_cast<std::uint8_t>(0x80u >> (x & 7));
            }
        }
    }

#ifdef _WIN32
    _setmode(_fileno(stdout), _O_BINARY);
#endif

    std::printf("P4\n%d %d\n", n, n);
    std::fwrite(image.data(), 1, image.size(), stdout);

    return 0;
}
